"""RESULTS-moods.md: how useful the creatures' faces are, next to the ranking methods. Generated."""

INTRO = (
    "The app draws every service as a creature whose face is its mood (`mood.ts`: restarted, sick,"
    " stressed, gone quiet, new phrase, fine). Here those moods are scored on real incidents."
    " Generated by `uv run bench moods`; do not edit by hand."
)
DATA = (
    " RCAEval RE2/RE3 incidents, logs only. Templates are mined once per incident, as for"
    " RootRank. Moods compare each service's last 2 minutes with the 15 before; RCAEval windows"
    " start 12 minutes before the fault, so early steps have a shorter baseline than in the app."
)
NOT_TUNED = (
    " Nothing was tuned on these results: the mood rules and thresholds are the app's, written"
    " before this benchmark existed."
)
RANKING = (
    "- **As a ranking:** services in the order they first look unwell after the fault (more"
    " serious mood first within a step). Ties are broken at random in expectation, never by name."
    " Intervals are 95% cluster bootstrap over (system, root service) groups, like every"
    " other result."
)
DISCLOSURE = (
    "- **Disclosure:** the moods have no training, so every incident is unseen by them. But their"
    " 'new phrase' mood uses RootRank's strongest signal (new message templates), which was"
    " found by the RootRank ablation over these same incidents. The idea, not any number, came"
    " from this data."
)


def _pct(x: float) -> str:
    return f"{100 * x:.1f}%"


def _ci(row: dict) -> str:
    return f"{_pct(row['value'])} ({100 * row['low']:.0f}-{100 * row['high']:.0f})"


def _gap(row: dict) -> str:
    return f"{100 * row['value']:+.1f} pts ({100 * row['low']:+.1f} to {100 * row['high']:+.1f})"


def _verdict(row: dict, k: int) -> str:
    """One plain sentence per k, decided by whether the paired interval excludes zero."""
    if row["low"] > 0:
        return f"At AC@{k}, RootRank is better than the faces."
    if row["high"] < 0:
        return f"At AC@{k}, the faces are better than RootRank."
    return f"At AC@{k}, the two cannot be told apart on these incidents."


def render_moods_report(result: dict, context: dict[str, dict]) -> str:
    offsets = result["offsets"]
    delay = result["median_delay_s"]
    delay_text = f", after a median of {delay:.0f} s" if delay is not None else ""
    rows = [
        f"| Faces: first service to look unwell | {_ci(result['ac1'])} | {_ci(result['ac3'])} |",
        *(f"| {name} | {_ci(r['ac1'])} | {_ci(r['ac3'])} |" for name, r in context.items()),
    ]
    findings = [
        f"- The broken service looks unwell within 5 minutes in"
        f" **{_pct(result['root_unwell_within_5min'])}** of incidents{delay_text}.",
        f"- Before anything broke (60 s before the fault) **{_pct(result['unwell_before_fault'])}**"
        " of services already looked unwell: the faces' false-alarm rate.",
        f"- By kind, AC@3: code faults {_ci(result['ac3_code'])},"
        f" resource faults {_ci(result['ac3_resource'])}.",
    ]
    return "\n".join(
        [
            "# ChronoBench: are the faces useful?",
            "",
            INTRO,
            "",
            "## How it was measured",
            "",
            f"- **Data:** all {result['cases']}{DATA}",
            f"- **Steps:** every {offsets[1] - offsets[0]} s from {offsets[0]} s"
            f" to +{offsets[-1]} s"
            f" around the fault.{NOT_TUNED}",
            RANKING,
            "",
            "## Results",
            "",
            "| Method | AC@1 | AC@3 |",
            "|---|---|---|",
            *rows,
            "",
            *findings,
            "",
            "## Faces against RootRank, paired",
            "",
            "Same incidents for both, so their shared difficulty cancels; an interval that"
            " excludes 0 is a real difference.",
            "",
            "| RootRank minus faces | Difference (95% interval) |",
            "|---|---|",
            f"| AC@1 | {_gap(result['rootrank_minus_faces']['ac1'])} |",
            f"| AC@3 | {_gap(result['rootrank_minus_faces']['ac3'])} |",
            "",
            _verdict(result["rootrank_minus_faces"]["ac1"], 1),
            _verdict(result["rootrank_minus_faces"]["ac3"], 3),
            "",
            "## Caveats",
            "",
            DISCLOSURE,
            "- The fault time is used only to choose when to look; the faces never see it.",
            "  RootRank's headline also uses the true start; RESULTS-autostart.md has it with an"
            " estimated start.",
            "",
            f"Code fingerprint (moods): `{result['fingerprint']}`.",
            "",
        ]
    )
